def largest_prime_factor_ref(n: int) -> int:
    best = None
    d = 2
    m = n
    while d * d <= m:
        if m % d == 0:
            best = d
            while m % d == 0:
                m //= d
        d += 1 if d == 2 else 2
    if m > 1:
        best = m if best is None else max(best, m)
    return best

def is_composite(n: int) -> bool:
